INSERT INTO "pages" ("id", "title", "body", "seo_description", "status")
VALUES (
  'terminos-y-condiciones',
  'Términos y condiciones',
  E'## 1. Identificación del proveedor\n\nMistikax es una tienda de ropa y calzado para hombre con domicilio en Lima, Perú. El canal oficial de atención es el WhatsApp publicado en la tienda y el correo hola@mistikax.com.\n\n## 2. Aceptación de los términos\n\nAl navegar, registrarte o confirmar un pedido aceptas estos términos y condiciones. Si no estás de acuerdo, te pedimos no utilizar los servicios de compra.\n\n## 3. Productos y disponibilidad\n\nLas prendas y el calzado se ofrecen según disponibilidad de stock. Las fotografías son referenciales y pueden existir variaciones de tono por la pantalla o la luz. Si un producto se agota después de tu pedido, te contactaremos para cambiarlo o devolver el importe pagado.\n\n## 4. Precios y formas de pago\n\nLos precios se expresan en soles peruanos e incluyen los impuestos aplicables. Aceptamos transferencia bancaria y pago contra entrega, según la zona y la configuración vigente. El pedido se prepara cuando el pago es confirmado o cuando se valida la entrega contra reembolso.\n\n## 5. Pedidos y confirmación\n\nEl pedido queda registrado con un número correlativo. La confirmación por WhatsApp no reemplaza la validación de stock y pago. Nos reservamos el derecho de cancelar pedidos con datos incompletos, intentos de fraude o errores evidentes de precio, informando al cliente y devolviendo lo pagado.\n\n## 6. Envíos y entregas\n\nPreparamos los pedidos en un plazo de 24 a 48 horas hábiles. El delivery en Lima Metropolitana tiene una tarifa de S/ 10 y en Lima periférica de S/ 15. El courier a provincias cuesta S/ 20. El recojo en tienda no tiene costo. El envío es gratuito desde S/ 200. Los plazos de transporte se cuentan desde el despacho y pueden variar por feriados, clima o disponibilidad de la agencia.\n\n## 7. Cambios, devoluciones y garantía\n\nPuedes solicitar el cambio de talla dentro de los 7 días calendario siguientes a la entrega. La prenda debe estar sin uso, con etiquetas y en su empaque original. No se aceptan cambios de ropa interior, accesorios de higiene ni prendas personalizadas. Si el producto presenta una falla de fabricación, coordinaremos la reparación, el cambio o la devolución conforme a la normativa de protección al consumidor.\n\n## 8. Datos personales\n\nTratamos tus datos para gestionar el pedido, coordinar la entrega y atender consultas, conforme a la Ley N.° 29733 de Protección de Datos Personales. No vendemos tus datos. Puedes solicitar acceso, rectificación o cancelación escribiendo a hola@mistikax.com.\n\n## 9. Propiedad intelectual\n\nEl nombre Mistikax, sus textos, fotografías, diseños y elementos gráficos son de titularidad de la tienda o se usan con autorización. No está permitida su reproducción sin consentimiento previo.\n\n## 10. Responsabilidad y ley aplicable\n\nAtendemos reclamos y consultas por los canales oficiales. Si no obtienes una solución, puedes acudir a INDECOPI. Estos términos se rigen por las leyes de la República del Perú y cualquier controversia se somete a los jueces de Lima.\n\n## 11. Vigencia y modificaciones\n\nEstos términos rigen desde su publicación. Podemos actualizarlos para reflejar cambios operativos o legales; la versión vigente será siempre la publicada en esta página.',
  'Condiciones de compra, pagos, envíos, cambios y tratamiento de datos de Mistikax.',
  'published'
)
ON CONFLICT ("id") DO NOTHING;
